points_sf_pre=st_transform(points_sf_pre, crs=st_crs(intersections_Cleveland_1910))
matches_pre=st_intersects(points_sf_pre, polygon_sf)
matches_pre=unique(as.vector(unlist(matches_pre)))

intersections_Cleveland_1910=st_drop_geometry(intersections_Cleveland_1910)

