    intersections_Cincinnati_1910[,j]*as.numeric(intersections_Cincinnati_1910$proportion_intersected)
  )[,j]
}

intersections_Cincinnati_1910$black_pop=as.numeric(intersections_Cincinnati_1910$bpop*intersections_Cincinnati_1910$proportion_intersected)
