intersections_Cincinnati_1910$usa=intersections_Cincinnati_1910$usa - intersections_Cincinnati_1910$black_pop

hex_mat_Cincinnati_1910=matrix(nrow=length(unique(intersections_Cincinnati_1910$hex_id)), ncol=18)
colnames(hex_mat_Cincinnati_1910)=c(
  "hex_id","pop","italian_pop","pop_mlp","pop_abe","pop_cs",
  "incarc_mlp","incarc_abe","incarc_cs","mori","non_mori_sicilians",
  "cutrera_1900_sicilians","damiani_1885_sicilians","cutrera_or_damiani_maps_sicilians",
  "all_sicilians","area","foreign","ethnic_frag"
)

hex_mat_Cincinnati_1910[,"hex_id"]=unique(intersections_Cincinnati_1910$hex_id)
