hex_mat_Philadelphia_1910$mafia_pre_geo=ifelse(hex_mat_Philadelphia_1910$hex_id %in% matches_pre, 1, 0)

hex_mat_Philadelphia_1910$mafia_book_hex=ifelse(hex_mat_Philadelphia_1910$hex_id %in% mafia_book_hex, 1, 0)
