points_sf=st_as_sf(points_df, coords = c("longitude","latitude"), crs = 4326)
points_sf=st_transform(points_sf, crs=st_crs(intersections_StLouis_1910))
polygon_sf=st_as_sf(intersections_StLouis_1910$geometry, crs=st_crs(intersections_StLouis_1910))
matches_book=st_intersects(points_sf, polygon_sf)
matches_book=unique(as.vector(unlist(matches_book)))

# Pre-1926 addresses
points_df_pre=data.frame(longitude = addresses_pre_1926$lon, latitude = addresses_pre_1926$lat)
points_sf_pre=st_as_sf(points_df_pre, coords = c("longitude","latitude"), crs = 4326)
points_sf_pre=st_transform(points_sf_pre, crs=st_crs(intersections_StLouis_1910))
matches_pre=st_intersects(points_sf_pre, polygon_sf)
matches_pre=unique(as.vector(unlist(matches_pre)))

intersections_StLouis_1910=st_drop_geometry(intersections_StLouis_1910)

matches_book=intersections_StLouis_1910[matches_book, "hex_id"]
matches_pre=intersections_StLouis_1910[matches_pre, "hex_id"]

hex_mat_StLouis_1910$mafia_book_geo=ifelse(hex_mat_StLouis_1910$hex_id %in% matches_book, 1, 0)
hex_mat_StLouis_1910$mafia_pre_geo=ifelse(hex_mat_StLouis_1910$hex_id %in% matches_pre, 1, 0)

hex_mat_StLouis_1910$mafia_book_hex=ifelse(hex_mat_StLouis_1910$hex_id %in% mafia_book_hex, 1, 0)
hex_mat_StLouis_1910$mafia_pre_hex=ifelse(hex_mat_StLouis_1910$hex_id %in% mafia_pre_hex, 1, 0)

hex_mat_StLouis_1910$cutrera_hex= ifelse(hex_mat_StLouis_1910$hex_id %in% cutrera_hex, 1, 0)
hex_mat_StLouis_1910$damiani_hex=ifelse(hex_mat_StLouis_1910$hex_id %in% damiani_hex, 1, 0)
hex_mat_StLouis_1910$cutrera_or_damiani_hex=ifelse(hex_mat_StLouis_1910$hex_id %in% cutrera_or_damiani_hex, 1, 0)

save(hex_mat_StLouis_1910, file="intermediate_outputs/step_3_hex_mats/hex_mat_StLouis_1910.rda")






