for (i in 1:nrow(Brooklyn_mori)){
  Brooklyn_mori[i,"all_sicilians"]=nrow(household_sample_1920[which(household_sample_1920$ed==Brooklyn_mori[i,"ed"]),])
  Brooklyn_mori[i,"mori_sicilians"]=nrow(household_sample_mori_1920[which(household_sample_mori_1920$ed==Brooklyn_mori[i,"ed"]),])
  Brooklyn_mori[i,"non_mori_sicilians"]=nrow(household_sample_non_mori_1920[which(household_sample_non_mori_1920$ed==Brooklyn_mori[i,"ed"]),])
  Brooklyn_mori[i,"cutrera_1900_sicilians"]=nrow(household_sample_cutrera_1900_1920[which(household_sample_cutrera_1900_1920$ed==Brooklyn_mori[i,"ed"]),])
  Brooklyn_mori[i,"damiani_1885_sicilians"]=nrow(household_sample_damiani_1885_1920[which(household_sample_damiani_1885_1920$ed==Brooklyn_mori[i,"ed"]),])
  Brooklyn_mori[i,"cutrera_or_damiani_maps_sicilians"]=nrow(household_sample_cutrera_or_damiani_maps_1920[which(household_sample_cutrera_or_damiani_maps_1920$ed==Brooklyn_mori[i,"ed"]),])
}

