Brooklyn_mori$cutrera_1900_sicilians=as.numeric(Brooklyn_mori$cutrera_1900_sicilians)
Brooklyn_mori$damiani_1885_sicilians=as.numeric(Brooklyn_mori$damiani_1885_sicilians)
Brooklyn_mori$cutrera_or_damiani_maps_sicilians=as.numeric(Brooklyn_mori$cutrera_or_damiani_maps_sicilians)

intersections_Brooklyn_1920$mori=Brooklyn_mori[match(intersections_Brooklyn_1920$ED, Brooklyn_mori$ed),"mori_sicilians"]
intersections_Brooklyn_1920$non_mori_sicilians=Brooklyn_mori[match(intersections_Brooklyn_1920$ED, Brooklyn_mori$ed),"non_mori_sicilians"]
intersections_Brooklyn_1920$all_sicilians=Brooklyn_mori[match(intersections_Brooklyn_1920$ED, Brooklyn_mori$ed),"all_sicilians"]
intersections_Brooklyn_1920$cutrera_1900_sicilians=Brooklyn_mori[match(intersections_Brooklyn_1920$ED, Brooklyn_mori$ed),"cutrera_1900_sicilians"]
intersections_Brooklyn_1920$damiani_1885_sicilians=Brooklyn_mori[match(intersections_Brooklyn_1920$ED, Brooklyn_mori$ed),"damiani_1885_sicilians"]
intersections_Brooklyn_1920$cutrera_or_damiani_maps_sicilians=Brooklyn_mori[match(intersections_Brooklyn_1920$ED, Brooklyn_mori$ed),"cutrera_or_damiani_maps_sicilians"]

