  ]
)
intersections_Brooklyn_1920$mori_weighted=intersections_Brooklyn_1920$mori*intersections_Brooklyn_1920$proportion_intersected
intersections_Brooklyn_1920$non_mori_sicilians_weighted=intersections_Brooklyn_1920$non_mori_sicilians*intersections_Brooklyn_1920$proportion_intersected
intersections_Brooklyn_1920$cutrera_1900_sicilians_weighted=intersections_Brooklyn_1920$cutrera_1900_sicilians*intersections_Brooklyn_1920$proportion_intersected
intersections_Brooklyn_1920$damiani_1885_sicilians_weighted=intersections_Brooklyn_1920$damiani_1885_sicilians*intersections_Brooklyn_1920$proportion_intersected
intersections_Brooklyn_1920$cutrera_or_damiani_maps_sicilians_weighted=intersections_Brooklyn_1920$cutrera_or_damiani_maps_sicilians*intersections_Brooklyn_1920$proportion_intersected
intersections_Brooklyn_1920$all_sicilians_weighted=intersections_Brooklyn_1920$all_sicilians*intersections_Brooklyn_1920$proportion_intersected
intersections_Brooklyn_1920$foreign_weighted=intersections_Brooklyn_1920$immpop*intersections_Brooklyn_1920$proportion_intersected

intersections_Brooklyn_1920$uk=as.numeric(ethnic_frag_1920[match(intersections_Brooklyn_1920$ED, ethnic_frag_1920$ed),"United Kingdom"])
intersections_Brooklyn_1920$usa=as.numeric(ethnic_frag_1920[match(intersections_Brooklyn_1920$ED, ethnic_frag_1920$ed),"USA"])
