intersections_Brooklyn_1920$russia=as.numeric(ethnic_frag_1920[match(intersections_Brooklyn_1920$ED, ethnic_frag_1920$ed),"Russia/Empire"])
intersections_Brooklyn_1920$west_euro=as.numeric(ethnic_frag_1920[match(intersections_Brooklyn_1920$ED, ethnic_frag_1920$ed),"Other Western Europe"])
intersections_Brooklyn_1920$east_asia=as.numeric(ethnic_frag_1920[match(intersections_Brooklyn_1920$ED, ethnic_frag_1920$ed),"East Asia"])
intersections_Brooklyn_1920$latin_america=as.numeric(ethnic_frag_1920[match(intersections_Brooklyn_1920$ED, ethnic_frag_1920$ed),"Latin America/ Caribbean"])
intersections_Brooklyn_1920$south_euro=as.numeric(ethnic_frag_1920[match(intersections_Brooklyn_1920$ED, ethnic_frag_1920$ed),"Other Southern Europe"])
intersections_Brooklyn_1920$africa=as.numeric(ethnic_frag_1920[match(intersections_Brooklyn_1920$ED, ethnic_frag_1920$ed),"Africa"])
intersections_Brooklyn_1920$scandanavia=as.numeric(ethnic_frag_1920[match(intersections_Brooklyn_1920$ED, ethnic_frag_1920$ed),"Scandinavia"])
intersections_Brooklyn_1920$italy=as.numeric(ethnic_frag_1920[match(intersections_Brooklyn_1920$ED, ethnic_frag_1920$ed),"Italy"])
intersections_Brooklyn_1920$southeast_asia=as.numeric(ethnic_frag_1920[match(intersections_Brooklyn_1920$ED, ethnic_frag_1920$ed),"Southeast Asia"])
intersections_Brooklyn_1920$other_euro=as.numeric(ethnic_frag_1920[match(intersections_Brooklyn_1920$ED, ethnic_frag_1920$ed),"Other Europe"])
intersections_Brooklyn_1920$middle_east=as.numeric(ethnic_frag_1920[match(intersections_Brooklyn_1920$ED, ethnic_frag_1920$ed),"Middle East"])
intersections_Brooklyn_1920$other=as.numeric(ethnic_frag_1920[match(intersections_Brooklyn_1920$ED, ethnic_frag_1920$ed),"Other"])
intersections_Brooklyn_1920$india=as.numeric(ethnic_frag_1920[match(intersections_Brooklyn_1920$ED, ethnic_frag_1920$ed),"India and Southern Asia"])
intersections_Brooklyn_1920$pacific=as.numeric(ethnic_frag_1920[match(intersections_Brooklyn_1920$ED, ethnic_frag_1920$ed),"Australia and Pacific Islands"])
intersections_Brooklyn_1920$other_asia=as.numeric(ethnic_frag_1920[match(intersections_Brooklyn_1920$ED, ethnic_frag_1920$ed),"Other Asia"])

ethnic_weight_cols=c(
  "uk",
  "usa",
  "east_euro",
  "ireland",
  "canada",
  "russia",
  "west_euro",
  "east_asia",
  "latin_america",
  "south_euro",
  "africa",
  "scandanavia",
  "italy",
  "southeast_asia",
  "other_euro",
  "middle_east",
  "other",
  "india",
  "pacific",
  "other_asia"
)

for (j in ethnic_weight_cols){
  intersections_Brooklyn_1920[,j]=st_drop_geometry(
    intersections_Brooklyn_1920[,j]*as.numeric(intersections_Brooklyn_1920$proportion_intersected)
  )[,j]
}

intersections_Brooklyn_1920$black_pop=as.numeric(intersections_Brooklyn_1920$bpop*intersections_Brooklyn_1920$proportion_intersected)
intersections_Brooklyn_1920$black_pop=intersections_Brooklyn_1920$black_pop - intersections_Brooklyn_1920$africa
intersections_Brooklyn_1920$usa=intersections_Brooklyn_1920$usa - intersections_Brooklyn_1920$black_pop

hex_mat_Brooklyn_1920=matrix(nrow=length(unique(intersections_Brooklyn_1920$hex_id)), ncol=18)
colnames(hex_mat_Brooklyn_1920)=c(
  "hex_id","pop","italian_pop","pop_mlp","pop_abe","pop_cs",
  "incarc_mlp","incarc_abe","incarc_cs","mori","non_mori_sicilians",
  "cutrera_1900_sicilians","damiani_1885_sicilians","cutrera_or_damiani_maps_sicilians",
  "all_sicilians","area","foreign","ethnic_frag"
)

hex_mat_Brooklyn_1920[,"hex_id"]=unique(intersections_Brooklyn_1920$hex_id)
hex_mat_Brooklyn_1920=as.data.frame(hex_mat_Brooklyn_1920)

hex_mat_Brooklyn_1920$median_home_value=NA_real_
hex_mat_Brooklyn_1920$median_home_value_coverage=NA_real_

intersections_Brooklyn_1920=st_drop_geometry(intersections_Brooklyn_1920)
intersections_Brooklyn_1910=st_drop_geometry(intersections_Brooklyn_1910)

ethnic_frag_cols=c(
  "uk",
  "usa",
  "east_euro",
  "ireland",
  "canada",
  "russia",
  "west_euro",
  "east_asia",
  "latin_america",
  "south_euro",
  "africa",
  "scandanavia",
  "italy",
  "southeast_asia",
  "other_euro",
  "middle_east",
  "other",
  "india",
  "pacific",
  "other_asia",
  "black_pop"
)

for (i in 1:nrow(hex_mat_Brooklyn_1920)){
  hex_mat_Brooklyn_1920[i,"pop"]=sum(intersections_Brooklyn_1920[which(intersections_Brooklyn_1920$hex_id==hex_mat_Brooklyn_1920[i,"hex_id"]),"pop_weighted"])
  hex_mat_Brooklyn_1920[i,"italian_pop"]=sum(intersections_Brooklyn_1920[which(intersections_Brooklyn_1920$hex_id==hex_mat_Brooklyn_1920[i,"hex_id"]),"ital_weighted"])
  hex_mat_Brooklyn_1920[i,"pop_mlp"]=sum(intersections_Brooklyn_1910[which(intersections_Brooklyn_1910$hex_id==hex_mat_Brooklyn_1920[i,"hex_id"]),"pop_mlp_weighted"])
  hex_mat_Brooklyn_1920[i,"pop_abe"]=sum(intersections_Brooklyn_1910[which(intersections_Brooklyn_1910$hex_id==hex_mat_Brooklyn_1920[i,"hex_id"]),"pop_abe_weighted"])
  hex_mat_Brooklyn_1920[i,"pop_cs"]=sum(intersections_Brooklyn_1910[which(intersections_Brooklyn_1910$hex_id==hex_mat_Brooklyn_1920[i,"hex_id"]),"pop_cs_weighted"])
  hex_mat_Brooklyn_1920[i,"incarc_mlp"]=sum(intersections_Brooklyn_1910[which(intersections_Brooklyn_1910$hex_id==hex_mat_Brooklyn_1920[i,"hex_id"]),"incarc_mlp_weighted"])
  hex_mat_Brooklyn_1920[i,"incarc_abe"]=sum(intersections_Brooklyn_1910[which(intersections_Brooklyn_1910$hex_id==hex_mat_Brooklyn_1920[i,"hex_id"]),"incarc_abe_weighted"])
  hex_mat_Brooklyn_1920[i,"incarc_cs"]=sum(intersections_Brooklyn_1910[which(intersections_Brooklyn_1910$hex_id==hex_mat_Brooklyn_1920[i,"hex_id"]),"incarc_cs_weighted"])
  hex_mat_Brooklyn_1920[i,"mori"]=sum(intersections_Brooklyn_1920[which(intersections_Brooklyn_1920$hex_id==hex_mat_Brooklyn_1920[i,"hex_id"]),"mori_weighted"])
  hex_mat_Brooklyn_1920[i,"non_mori_sicilians"]=sum(intersections_Brooklyn_1920[which(intersections_Brooklyn_1920$hex_id==hex_mat_Brooklyn_1920[i,"hex_id"]),"non_mori_sicilians_weighted"])
  hex_mat_Brooklyn_1920[i,"cutrera_1900_sicilians"]=sum(intersections_Brooklyn_1920[which(intersections_Brooklyn_1920$hex_id==hex_mat_Brooklyn_1920[i,"hex_id"]),"cutrera_1900_sicilians_weighted"])
  hex_mat_Brooklyn_1920[i,"damiani_1885_sicilians"]=sum(intersections_Brooklyn_1920[which(intersections_Brooklyn_1920$hex_id==hex_mat_Brooklyn_1920[i,"hex_id"]),"damiani_1885_sicilians_weighted"])
  hex_mat_Brooklyn_1920[i,"cutrera_or_damiani_maps_sicilians"]=sum(intersections_Brooklyn_1920[which(intersections_Brooklyn_1920$hex_id==hex_mat_Brooklyn_1920[i,"hex_id"]),"cutrera_or_damiani_maps_sicilians_weighted"])
  hex_mat_Brooklyn_1920[i,"all_sicilians"]=sum(intersections_Brooklyn_1920[which(intersections_Brooklyn_1920$hex_id==hex_mat_Brooklyn_1920[i,"hex_id"]),"all_sicilians_weighted"])
  hex_mat_Brooklyn_1920[i,"area"]=sum(intersections_Brooklyn_1920[which(intersections_Brooklyn_1920$hex_id==hex_mat_Brooklyn_1920[i,"hex_id"]),"area_intersect"])
  hex_mat_Brooklyn_1920[i,"foreign"]=sum(intersections_Brooklyn_1920[which(intersections_Brooklyn_1920$hex_id==hex_mat_Brooklyn_1920[i,"hex_id"]),"foreign_weighted"])
  
  home_value_rows=which(
    intersections_Brooklyn_1920$hex_id==hex_mat_Brooklyn_1920[i,"hex_id"]
  )
  
  valid_home_value_rows=home_value_rows[
    !is.na(intersections_Brooklyn_1920$median_home_value[home_value_rows]) &
      intersections_Brooklyn_1920$pop_weighted[home_value_rows] > 0
  ]
  
  home_value_total_pop=sum(
    intersections_Brooklyn_1920$pop_weighted[home_value_rows],
    na.rm=TRUE
  )
  
  home_value_observed_pop=sum(
    intersections_Brooklyn_1920$pop_weighted[valid_home_value_rows],
    na.rm=TRUE
  )
  
  if (length(valid_home_value_rows)>0 && home_value_observed_pop>0){
    hex_mat_Brooklyn_1920[i,"median_home_value"]=weighted.mean(
      intersections_Brooklyn_1920$median_home_value[valid_home_value_rows],
      intersections_Brooklyn_1920$pop_weighted[valid_home_value_rows],
      na.rm=TRUE
    )
  } else {
    hex_mat_Brooklyn_1920[i,"median_home_value"]=NA_real_
  }
  
  hex_mat_Brooklyn_1920[i,"median_home_value_coverage"]=ifelse(
    home_value_total_pop>0,
    home_value_observed_pop/home_value_total_pop,
    NA_real_
  )
  
  tmp=vector(mode="numeric", length=length(ethnic_frag_cols))
  
  for (j in seq_along(ethnic_frag_cols)){
    tmp[j]=(sum(ifelse(
      is.na(intersections_Brooklyn_1920[
        which(intersections_Brooklyn_1920$hex_id==hex_mat_Brooklyn_1920[i,"hex_id"]),
        ethnic_frag_cols[j]
      ]),
      0,
      intersections_Brooklyn_1920[
        which(intersections_Brooklyn_1920$hex_id==hex_mat_Brooklyn_1920[i,"hex_id"]),
        ethnic_frag_cols[j]
      ]
    ))/hex_mat_Brooklyn_1920[i,"pop"])^2
  }
  
  hex_mat_Brooklyn_1920[i,"ethnic_frag"]=1-sum(tmp)
}

hex_mat_Brooklyn_1920$ital_prop=hex_mat_Brooklyn_1920$italian_pop/hex_mat_Brooklyn_1920$pop
hex_mat_Brooklyn_1920$incarc_abe_prop=hex_mat_Brooklyn_1920$incarc_abe/hex_mat_Brooklyn_1920$pop_abe
hex_mat_Brooklyn_1920$incarc_mlp_prop=hex_mat_Brooklyn_1920$incarc_mlp/hex_mat_Brooklyn_1920$pop_mlp
hex_mat_Brooklyn_1920$incarc_cs_prop=hex_mat_Brooklyn_1920$incarc_cs/hex_mat_Brooklyn_1920$pop_cs
hex_mat_Brooklyn_1920$any_mori=ifelse(hex_mat_Brooklyn_1920$mori>0, 1, 0)
hex_mat_Brooklyn_1920$any_non_mori_sicilians=ifelse(hex_mat_Brooklyn_1920$non_mori_sicilians>0, 1, 0)
hex_mat_Brooklyn_1920$any_cutrera_1900_sicilians=ifelse(hex_mat_Brooklyn_1920$cutrera_1900_sicilians>0, 1, 0)
hex_mat_Brooklyn_1920$any_damiani_1885_sicilians=ifelse(hex_mat_Brooklyn_1920$damiani_1885_sicilians>0, 1, 0)
hex_mat_Brooklyn_1920$any_cutrera_or_damiani_maps_sicilians=ifelse(hex_mat_Brooklyn_1920$cutrera_or_damiani_maps_sicilians>0, 1, 0)
hex_mat_Brooklyn_1920$any_sicilians=ifelse(hex_mat_Brooklyn_1920$all_sicilians>0, 1, 0)
hex_mat_Brooklyn_1920$foreign_prop=hex_mat_Brooklyn_1920$foreign/hex_mat_Brooklyn_1920$pop
hex_mat_Brooklyn_1920$year=1920
hex_mat_Brooklyn_1920$city="Brooklyn"

intersections_Brooklyn_1920$working_age_pop=census_econ[match(intersections_Brooklyn_1920$ED, census_econ$ed), "wap"]
intersections_Brooklyn_1920$household_count=census_econ[match(intersections_Brooklyn_1920$ED, census_econ$ed), "hh"]
intersections_Brooklyn_1920$occ_score=census_econ[match(intersections_Brooklyn_1920$ED, census_econ$ed), "occ_score"]*intersections_Brooklyn_1920$working_age_pop
intersections_Brooklyn_1920$sei=census_econ[match(intersections_Brooklyn_1920$ED, census_econ$ed), "duncan"]*intersections_Brooklyn_1920$working_age_pop
intersections_Brooklyn_1920$owned=census_econ[match(intersections_Brooklyn_1920$ED, census_econ$ed), "owned"]*intersections_Brooklyn_1920$household_count
intersections_Brooklyn_1920$owned_free=census_econ[match(intersections_Brooklyn_1920$ED, census_econ$ed), "owned_free"]*intersections_Brooklyn_1920$household_count
intersections_Brooklyn_1920$rent=census_econ[match(intersections_Brooklyn_1920$ED, census_econ$ed), "rent"]*intersections_Brooklyn_1920$household_count
intersections_Brooklyn_1920$construction=census_econ[match(intersections_Brooklyn_1920$ED, census_econ$ed), "ind_cons"]*intersections_Brooklyn_1920$working_age_pop
