intersections_Chicago_1930$other_asia=as.numeric(ethnic_frag_1930[match(intersections_Chicago_1930$ED, ethnic_frag_1930$ed),"Other Asia"])

ethnic_weight_cols=c(
  "uk",
  "usa",
  "east_euro",
  "ireland",
  "canada",
  "russia",
