intersections_Chicago_1930$sei=census_econ[match(intersections_Chicago_1930$ED, census_econ$ed), "duncan"]*intersections_Chicago_1930$working_age_pop
intersections_Chicago_1930$owned=census_econ[match(intersections_Chicago_1930$ED, census_econ$ed), "owned"]*intersections_Chicago_1930$household_count
intersections_Chicago_1930$owned_free=census_econ[match(intersections_Chicago_1930$ED, census_econ$ed), "owned_free"]*intersections_Chicago_1930$household_count
intersections_Chicago_1930$rent=census_econ[match(intersections_Chicago_1930$ED, census_econ$ed), "rent"]*intersections_Chicago_1930$household_count
intersections_Chicago_1930$construction=census_econ[match(intersections_Chicago_1930$ED, census_econ$ed), "ind_cons"]*intersections_Chicago_1930$working_age_pop
intersections_Chicago_1930$transportation=census_econ[match(intersections_Chicago_1930$ED, census_econ$ed), "ind_trans"]*intersections_Chicago_1930$working_age_pop
intersections_Chicago_1930$retail_trade=census_econ[match(intersections_Chicago_1930$ED, census_econ$ed), "ind_rt"]*intersections_Chicago_1930$working_age_pop
