  hex_mat_Cleveland_1930[i,"pop_cs"]=sum(intersections_Cleveland_1920[which(intersections_Cleveland_1920$hex_id==hex_mat_Cleveland_1930[i,"hex_id"]),"pop_cs_weighted"])
