    intersections_Pittsburgh_1930[,j]*as.numeric(intersections_Pittsburgh_1930$proportion_intersected)
  )[,j]
}

intersections_Pittsburgh_1930$black_pop=as.numeric(intersections_Pittsburgh_1930$bpop*intersections_Pittsburgh_1930$proportion_intersected)
