intersections_Pittsburgh_1930$usa=intersections_Pittsburgh_1930$usa - intersections_Pittsburgh_1930$black_pop

hex_mat_Pittsburgh_1930=matrix(nrow=length(unique(intersections_Pittsburgh_1930$hex_id)), ncol=18)
