points_sf=st_transform(points_sf, crs=st_crs(intersections_Cleveland_1900))
polygon_sf=st_as_sf(intersections_Cleveland_1900$geometry, crs=st_crs(intersections_Cleveland_1900))
matches_book=st_intersects(points_sf, polygon_sf)
matches_book=unique(as.vector(unlist(matches_book)))

# Pre-1926 addresses
