intersections_Manhattan_1890=st_drop_geometry(intersections_Manhattan_1890)

ethnic_frag_cols=c(
  "uk",
  "usa",
  "east_euro",
  "ireland",
  "canada",
  "russia",
  "west_euro",
  "east_asia",
